59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        validateRequiredFields(ownerFieldsDto);
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
110	        this.clinicService.saveOwner(owner);
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        headers.setLocation(UriComponentsBuilder.newInstance()
113	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
114	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
115	    }
116	
117	    /**
118	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
119	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
120	     * so the client receives a 400 whose {@code errors} array lists each missing field.
121	     *
122	     * @param ownerFieldsDto the submitted owner fields
123	     */
124	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
125	        List<String> missingFields = new ArrayList<>();
126	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
127	            missingFields.add("firstName");
128	        }
129	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
130	            missingFields.add("lastName");
131	        }
132	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
133	            missingFields.add("address");
134	        }
135	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
136	            missingFields.add("city");
137	        }
138	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
139	            missingFields.add("telephone");
140	        }
141	        if (!missingFields.isEmpty()) {
142	            throw new MissingOwnerFieldsException(missingFields);
143	        }
144	    }
145	
146	    /**
147	     * Normalizes a telephone number for owner creation by stripping every non-digit character and
148	     * requiring exactly ten digits to remain. The stripped, ten-digit value is what gets stored and
149	     * returned.
150	     *
151	     * @param telephone the raw telephone value submitted by the client
152	     * @return the normalized ten-digit telephone number
153	     * @throws InvalidOwnerFieldsException if the value does not contain exactly ten digits after stripping
154	     */
155	    private String normalizeTelephone(String telephone) {
156	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
157	        if (digits.length() != 10) {
158	            throw new InvalidOwnerFieldsException(List.of("telephone"));
159	        }
160	        return digits;
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        currentOwner.setAddress(ownerFieldsDto.getAddress());
171	        currentOwner.setCity(ownerFieldsDto.getCity());
172	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
173	        currentOwner.setLastName(ownerFieldsDto.getLastName());
174	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
175	        this.clinicService.saveOwner(currentOwner);
176	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Transactional
181	    @Override
182	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        this.clinicService.deleteOwner(owner);
188	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
